function LadderCompetionSeasonRewardCellNode:RefreshData_()
    local cellData = self:GetCellData()
    ---@type LadderGradeVo
    local gradeVo  = checkTable(cellData.gradeVo)

    -- update icon
    CfUtils.FillImage(self.ImgSegment, gradeVo.icon)

    -- update title
    CfUtils.FillText(self.TextTitle, gradeVo.name2)

    -- update score
    CfUtils.FillText(self.TextScore, gradeVo.scoreBegin)
    
    local starCount = gradeVo.starPVP
    for i = 1, 5 do
        local child = self.StarGroup.transform:GetChild(i - 1)
        CfUtils.SetActive(child, i <= starCount)
    end

    local prizeIds = string.split(gradeVo.prizeId, ";")
    local prizeNums = string.split(gradeVo.prizeNum,";")
    local count = math.min(#prizeIds, #prizeNums)
    local data = {}
    for i = 1, count do
        data[i] = {}
        data[i].id = prizeIds[i]
        data[i].num = prizeNums[i]
    end
    -- update rewards
    if not isNull(self.CommonGoodsListLua_) then
        self.CommonGoodsListLua_:FreshBaseUI(data)
    end
end


return LadderCompetionSeasonRewardCellNode
